create extension if not exists pgcrypto;

create table if not exists public.mm2wild_cases (
  id bigint generated by default as identity primary key,
  source_case_id bigint unique,
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  name text not null check (length(trim(name)) > 0),
  image_url text not null,
  price numeric(20, 2) not null check (price > 0),
  volatility numeric(8, 6) not null check (volatility between 0 and 1),
  risk smallint not null check (risk between 0 and 2),
  marker numeric(6, 3) not null check (marker between 0 and 100),
  flags integer not null default 0,
  color text not null default '#000000',
  items jsonb not null check (jsonb_typeof(items) = 'array' and jsonb_array_length(items) > 0),
  active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_mm2wild_cases_active_sort
  on public.mm2wild_cases (active, sort_order, price desc);

create table if not exists public.mm2wild_case_openings (
  id uuid primary key default gen_random_uuid(),
  user_uuid uuid not null references public.mm2wild_users(uuid) on delete restrict,
  case_id bigint not null references public.mm2wild_cases(id) on delete restrict,
  quantity smallint not null check (quantity between 1 and 4),
  total_cost numeric(20, 2) not null check (total_cost > 0),
  total_value numeric(20, 2) not null check (total_value >= 0),
  results jsonb not null check (jsonb_typeof(results) = 'array' and jsonb_array_length(results) between 1 and 4),
  server_seed_hash text not null check (server_seed_hash ~ '^[0-9a-f]{64}$'),
  server_seed text not null check (server_seed ~ '^[0-9a-f]{64}$'),
  balance_after numeric(20, 2) not null check (balance_after >= 0),
  opened_at timestamptz not null default now()
);

create index if not exists idx_mm2wild_case_openings_user_opened
  on public.mm2wild_case_openings (user_uuid, opened_at desc);
create index if not exists idx_mm2wild_case_openings_case_opened
  on public.mm2wild_case_openings (case_id, opened_at desc);

