insert into public.mm2wild_cases (
  source_case_id, slug, name, image_url, price, volatility, risk, marker,
  flags, color, items, active, sort_order, updated_at
)
select
  (case_data->>'sourceCaseId')::bigint,
  case_data->>'slug',
  case_data->>'name',
  case_data->>'imageUrl',
  (case_data->>'price')::numeric,
  (case_data->>'volatility')::numeric,
  (case_data->>'risk')::smallint,
  (case_data->>'marker')::numeric,
  (case_data->>'flags')::integer,
  case_data->>'color',
  case_data->'items',
  true,
  position,
  now()
from seed
on conflict (slug) do update set
  source_case_id = excluded.source_case_id,
  name = excluded.name,
  image_url = excluded.image_url,
  price = excluded.price,
  volatility = excluded.volatility,
  risk = excluded.risk,
  marker = excluded.marker,
  flags = excluded.flags,
  color = excluded.color,
  items = excluded.items,
  active = excluded.active,
  sort_order = excluded.sort_order,
  updated_at = excluded.updated_at;

create or replace function public.mm2wild_record_case_opening(
  p_user_uuid uuid,
  p_case_id bigint,
  p_quantity integer,
  p_results jsonb,
  p_server_seed text,
  p_server_seed_hash text
) returns public.mm2wild_case_openings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_case public.mm2wild_cases%rowtype;
  v_user public.mm2wild_users%rowtype;
  v_opening public.mm2wild_case_openings%rowtype;
  v_total_cost numeric(20, 2);
  v_total_value numeric(20, 2);
  v_valid_results integer;
begin
  if p_quantity not between 1 and 4
     or jsonb_typeof(p_results) <> 'array'
     or jsonb_array_length(p_results) <> p_quantity then
    raise exception using errcode = 'P0001', message = 'Choose between 1 and 4 cases.';
  end if;
  if p_server_seed !~ '^[0-9a-f]{64}$' or p_server_seed_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = 'P0001', message = 'The opening fairness data is invalid.';
  end if;

  select * into v_case from public.mm2wild_cases where id = p_case_id and active = true for share;
  if v_case.id is null then
    raise exception using errcode = 'P0001', message = 'This case is unavailable.';
  end if;

  select count(*), coalesce(sum((case_item->>'price')::numeric), 0)
    into v_valid_results, v_total_value
  from jsonb_array_elements(p_results) result
  join lateral (
    select item as case_item
    from jsonb_array_elements(v_case.items) item
    where (item->>'itemId')::bigint = (result->>'itemId')::bigint
    limit 1
  ) matched on true;
  if v_valid_results <> p_quantity then
    raise exception using errcode = 'P0001', message = 'One or more case results are invalid.';
  end if;

  v_total_cost := v_case.price * p_quantity;
  update public.mm2wild_users
     set mm2_balance = mm2_balance - v_total_cost + v_total_value,
         total_wagered = total_wagered + v_total_cost,
         total_bets = total_bets + p_quantity,
         games_won = games_won + case when v_total_value >= v_total_cost then 1 else 0 end
   where uuid = p_user_uuid and mm2_balance >= v_total_cost
   returning * into v_user;
  if v_user.uuid is null then
    raise exception using errcode = 'P0001', message = 'Insufficient balance.';
  end if;

  insert into public.mm2wild_case_openings (
    user_uuid, case_id, quantity, total_cost, total_value, results,
    server_seed_hash, server_seed, balance_after
  ) values (
    p_user_uuid, v_case.id, p_quantity, v_total_cost, v_total_value, p_results,
    p_server_seed_hash, p_server_seed, v_user.mm2_balance
  ) returning * into v_opening;

  insert into public.mm2wild_bets (user_uuid, game, status, amount, profit, multiplier)
  values (
    p_user_uuid,
    'cases',
    case when v_total_value > v_total_cost then 'won'
         when v_total_value = v_total_cost then 'push'
         else 'lost' end,
    v_total_cost,
    v_total_value - v_total_cost,
    case when v_total_cost > 0 then round(v_total_value / v_total_cost, 2) else 0 end
  );

  return v_opening;
end;
$$;

alter table public.mm2wild_cases enable row level security;
alter table public.mm2wild_case_openings enable row level security;
revoke all on table public.mm2wild_cases from anon, authenticated;
revoke all on table public.mm2wild_case_openings from anon, authenticated;
revoke all on function public.mm2wild_record_case_opening(uuid, bigint, integer, jsonb, text, text)
  from public, anon, authenticated;
